{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "InternationalizationProvider",
    "displayName": "Internationalization Provider",
    "group": "Utilities",
    "category": "Utility",
    "isHiddenFromOverview": true,
    "keywords": [
      "i18n",
      "internationalization",
      "localization",
      "locale",
      "translation",
      "translations",
      "provider",
      "language"
    ],
    "usage": {
      "description": "Wraps your app to set the active locale and (optionally) merge additional translation catalogs + per-locale overrides. Astryx components inside the subtree resolve their strings against this context. If no provider is present, components fall back to the shipped English defaults.",
      "anatomy": [
        {
          "name": "Provider boundary",
          "required": true,
          "description": "A nonvisual context boundary that supplies locale, message catalogs, overrides, and direction to descendant Astryx components, and a calendar system to `Calendar`. It renders no DOM element."
        }
      ],
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use shipped Astryx locale catalogs from `@astryxdesign/core/locales/*` when one exists for your target locale."
        },
        {
          "guidance": true,
          "description": "Use a same-shape local catalog only when Astryx has not shipped that locale yet or you are testing in-progress translations."
        },
        {
          "guidance": true,
          "description": "Use real BCP 47 tags such as `fr-FR`, `pt-BR`, or `ar-SA`; regional locales fall back to their base language before English."
        },
        {
          "guidance": true,
          "description": "Set the `dir` attribute on `<html>` (or a wrapping element) yourself; the provider does not set it. Astryx components mirror layout and directional icons from the DOM `dir`, so an RTL locale won't visually mirror without it. Use `getLocaleDirection(locale)` to derive the value for both the provider and the DOM."
        },
        {
          "guidance": true,
          "description": "Set `calendar` to show `Calendar`, `DateInput`, `DateRangeInput`, and `DateTimeInput` in another calendar system and write Timestamp, PowerSearch, and Schedule dates in it. A locale never selects the calendar: `fa-IR` shows Gregorian dates until you set `calendar=\"persian\"`, and a `-u-ca-` keyword in `locale`, as in `th-TH-u-ca-buddhist`, keeps Gregorian dates too. Date values stay Gregorian ISO strings."
        },
        {
          "guidance": false,
          "description": "Cast custom catalog maps to `any`; the i18n package exports `ProviderMessagesByLocale`, `MessagesByLocale`, `Catalog`, and `RuntimeCatalog` for local catalog typing."
        }
      ]
    },
    "props": [
      {
        "name": "locale",
        "type": "string",
        "required": true,
        "description": "BCP 47 language tag for the active locale (e.g. \"en\", \"pt\", \"pt-BR\", \"zh-Hans\"). Regional tags fall back to their base language, then to the shipped \"en\" catalog."
      },
      {
        "name": "messages",
        "type": "ProviderMessagesByLocale",
        "required": false,
        "description": "Optional map of BCP 47 tag to a rich or generated runtime catalog. Import compact shipped catalogs from `@astryxdesign/core/locales/*.generated.js`; the shipped \"en\" catalog is always available and does not need to be listed here."
      },
      {
        "name": "overrides",
        "type": "Overrides",
        "required": false,
        "description": "Sparse per-locale key overrides applied on top of shipped defaults. Overrides are locale-keyed so a runtime locale swap picks up the correct set."
      },
      {
        "name": "dir",
        "type": "'ltr' | 'rtl'",
        "required": false,
        "description": "Explicit text-direction override for the context. When omitted, direction is derived from `locale` via `Intl.Locale.getTextInfo()`. This sets the direction Astryx reads, but it does NOT set the DOM `dir` attribute; you must set `dir` on `<html>` (or a wrapping element) yourself, since Astryx components mirror layout and directional icons from the DOM `dir`, not from this prop. Set both to the same value and keep them in sync."
      },
      {
        "name": "calendar",
        "type": "'gregory' | 'iso8601' | 'buddhist' | 'roc' | 'japanese' | 'persian' | 'indian' | 'hebrew' | 'chinese' | 'dangi' | 'coptic' | 'ethiopic' | 'ethioaa' | 'islamic-civil' | 'islamic-tbla' | 'islamic-umalqura'",
        "required": false,
        "description": "Calendar system of the subtree, such as 'persian', 'hebrew', or 'buddhist'. `Calendar`, `DateInput`, `DateRangeInput`, and `DateTimeInput` show it, and Timestamp, PowerSearch, and Lab's Schedule write their dates in it. When omitted, the calendar is Gregorian: a locale never selects it, neither by its default calendar nor by a `-u-ca-` keyword. A component's own `calendar` prop takes precedence. Values stay Gregorian ISO dates. Calendars other than gregory, iso8601, buddhist, roc, and japanese need `Temporal`; the context keeps the requested calendar, and where the runtime lacks `Temporal`, these components show Gregorian dates and warn in development. Load a polyfill such as `temporal-polyfill/full/global` on the server and in the browser."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "required": true,
        "description": "Content to render with the internationalization provider."
      }
    ],
    "examples": [
      {
        "label": "Load a shipped Astryx locale catalog",
        "code": "import type {ReactNode} from 'react';\nimport {InternationalizationProvider} from '@astryxdesign/core/i18n';\nimport frFR from '@astryxdesign/core/locales/fr-FR.generated.js';\n\nexport function AppI18n({children}: {children: ReactNode}) {\n  return (\n    <InternationalizationProvider locale=\"fr-FR\" messages={{'fr-FR': frFR}}>\n      {children}\n    </InternationalizationProvider>\n  );\n}"
      },
      {
        "label": "Override one Astryx string",
        "code": "import type {ReactNode} from 'react';\nimport {InternationalizationProvider} from '@astryxdesign/core/i18n';\n\nexport function AppI18n({children}: {children: ReactNode}) {\n  return (\n    <InternationalizationProvider\n      locale=\"en\"\n      overrides={{\n        en: {'@astryx.selector.placeholder': 'Choose...'},\n      }}\n    >\n      {children}\n    </InternationalizationProvider>\n  );\n}"
      },
      {
        "label": "Show Calendar in the Persian calendar",
        "code": "import type {ReactNode} from 'react';\nimport {InternationalizationProvider} from '@astryxdesign/core/i18n';\n\n// Values stay Gregorian ISO dates, for example '2026-10-30'.\nexport function AppI18n({children}: {children: ReactNode}) {\n  return (\n    <InternationalizationProvider locale=\"fa-IR\" calendar=\"persian\">\n      {children}\n    </InternationalizationProvider>\n  );\n}"
      },
      {
        "label": "Provide a local fallback catalog",
        "code": "import type {ReactNode} from 'react';\nimport {\n  InternationalizationProvider,\n  type MessagesByLocale,\n} from '@astryxdesign/core/i18n';\nimport ptBR from './locales/pt-BR.json';\n\nconst messages: MessagesByLocale = {'pt-BR': ptBR};\n\nexport function AppI18n({children}: {children: ReactNode}) {\n  return (\n    <InternationalizationProvider locale=\"pt-BR\" messages={messages}>\n      {children}\n    </InternationalizationProvider>\n  );\n}"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/i18n",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
